async function drainIce(id){const pc=peers.get(id),queue=pendingIce.get(id)||[];pendingIce.delete(id);for(const candidate of queue)try{await pc.addIceCandidate(candidate)}catch{}}
async function answerOffer(id,offer){const pc=connection(id);if(pc.signalingState==='have-remote-offer')return;const polite=uid.localeCompare(id)>0,collision=pc.makingOffer||pc.signalingState!=='stable';if(collision&&!polite){pc.ignoreOffer=true;return}try{pc.ignoreOffer=false;if(collision&&pc.signalingState==='have-local-offer')await pc.setLocalDescription({type:'rollback'});await pc.setRemoteDescription(offer);await syncLocalSenders(pc);await drainIce(id);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);pc.needsNegotiation=false;await send({type:'answer',to:id,answer:pc.localDescription})}catch(error){console.warn('Não foi possível responder ao vídeo do outro jogador',error)}}async function handleRoomEvent(e){if(e.from===uid&&e.type!=='kick'&&e.type!=='chat')return;if(e.type==='join'){creatorId=e.creator||creatorId;players.set(e.from,{id:e.from,name:e.name||'Aventureiro',mediaReady:false,cameraOn:true});if(active)connection(e.from);renderPlayers();if(media)announceMediaReady();if(sharedMusicTracks.length&&musicOwner===uid){await send({type:'music-playlist',tracks:sharedMusicTracks,owner:uid,index:currentMusicIndex,playing:!sharedMusicAudio.paused,time:sharedMusicAudio.currentTime,at:Date.now()+700,to:e.from})}}else if(e.type==='chat'){handleChatEvent(e)}else if(e.type==='book-added'||e.type==='book-removed'){await loadRoomBooks()}else if(e.type==='temporary-image'){showTemporaryImage(e.image,e.sender||players.get(e.from)?.name||'Aventureiro')}else if(e.type==='music-playlist'){await setSharedMusicPlaylist(e.tracks,e.owner||e.from,e.index||0);await applyMusicControl({action:e.playing?'play':'pause',time:e.time,at:e.at})}else if(e.type==='music-control')await applyMusicControl(e);else if(e.type==='leave'){removePlayer(e.from);if(musicOwner===e.from){musicOwner=[...players.keys()].sort()[0]||null}}else if(e.type==='media-stopped'){const player=players.get(e.from);if(player){player.mediaReady=false;player.hasVideo=false;player.cameraOn=false}dropVideoStream(e.from)}else if(e.type==='kick'){if(e.target===uid){leaveRoom(false);toast('O criador removeu você da sala.')}else removePlayer(e.target)}else if(e.type==='roll'){renderRoll(e.roll,true);$('#rollStatus').textContent=`ROLAGEM DE ${(e.roll.name||'AVENTUREIRO').toUpperCase()}`}else if(e.type==='clear')$('#history').innerHTML='';else if(e.type==='media-ready'){const player=players.get(e.from);if(player){player.mediaReady=true;player.hasVideo=Boolean(e.hasVideo);player.cameraOn=e.cameraOn!==false;if(active)connection(e.from);if(media)maybeConnect(e.from,true)}}else if(e.type==='camera-state'){const player=players.get(e.from);if(player)player.cameraOn=e.cameraOn!==false;setCameraVisual(e.from,e.cameraOn!==false)}else if(e.type==='offer')await answerOffer(e.from,e.offer);else if(e.type==='answer'){const pc=peers.get(e.from);if(pc&&pc.signalingState==='have-local-offer'){pc.ignoreOffer=false;await pc.setRemoteDescription(e.answer);await drainIce(e.from)}}else if(e.type==='ice')await receiveIce(e.from,e.candidate)}
async function poll(){if(polling)return;polling=true;while(true){try{const response=await fetch(`/api/events?room=${encodeURIComponent(room)}&since=${cursor}&player=${encodeURIComponent(uid)}`),data=await response.json();for(const item of data.events||[]){cursor=Math.max(cursor,item.id);const event=item.event;if(event.to&&event.to!==uid&&event.from!==uid)continue;await handleRoomEvent(event)}}catch{await new Promise(resolve=>setTimeout(resolve,1200))}}}
$('#videoGrid').addEventListener('click',event=>{if(event.target.closest('#cameraBtn'))toggleMedia();else if(event.target.closest('[data-camera-toggle]'))toggleCameraTrack();else if(event.target.closest('[data-video-settings]'))renderCameraOptions(event.target.closest('[data-video-settings]'))});document.addEventListener('click',event=>{const option=event.target.closest('[data-camera-background]');if(option)setCameraBackground(option.dataset.cameraBackground);if(event.target.closest('[data-close-background-menu]'))closeCameraOptions();if(!event.target.closest('#cameraOptionsMenu')&&!event.target.closest('[data-video-settings]'))closeCameraOptions()});document.addEventListener('change',event=>{if(event.target.matches('#customBackgroundInput'))setCustomCameraBackground(event.target.files[0])});
$('#videoGrid').addEventListener('click',event=>{if(event.target.closest('[data-mic-toggle]')){const button=event.target.closest('[data-mic-toggle]');handleMicClick(button)}else if(event.target.closest('[data-speaker-toggle]'))handleSpeakerClick(event.target.closest('[data-speaker-toggle]'));else if(event.target.closest('[data-end-transmission]'))stopMediaTransmission()});$('#videoGrid').addEventListener('input',event=>{if(event.target.matches('[data-output-volume]'))changeOutputVolume(event.target.value)});$('#cameraAudioGain').addEventListener('input',event=>changeOutputVolume(event.target.value));$('#videoGrid').addEventListener('pointerdown',event=>{if(event.pointerType!=='touch')return;const tile=event.target.closest('.video-tile');if(tile?.id==='v-'+uid)revealVideoControls(tile)});

function dropVideoStream(id){peers.get(id)?.close();peers.delete(id);pendingIce.delete(id);remoteStreams.delete(id);const audioNode=remoteAudioNodes.get(id);if(audioNode){audioNode.source.disconnect();audioNode.gain.disconnect();audioNode.limiter?.disconnect();remoteAudioNodes.delete(id)}document.getElementById('v-'+id)?.remove();if(!$('#videoGrid').querySelector('.video-tile'))$('#videoGrid').innerHTML=videoPlaceholder()}
async function stopMediaTransmission(){if(!media)return;await send({type:'media-stopped'});if(backgroundPipeline){stopBackgroundPipeline(backgroundPipeline);backgroundPipeline=null;activeBackground='none'}if(customBackgroundUrl){URL.revokeObjectURL(customBackgroundUrl);customBackgroundUrl=null}media.getTracks().forEach(track=>track.stop());media=null;muted=false;[...peers.keys()].forEach(dropVideoStream);remoteStreams.clear();pendingIce.clear();const own=players.get(uid);if(own){own.mediaReady=false;own.hasVideo=false;own.cameraOn=false}document.getElementById('v-'+uid)?.remove();$('#videoGrid').innerHTML=videoPlaceholder();toast('Transmissão encerrada. A sala de jogo continua ativa.')}
async function leaveRoom(announce=true){if(!active)return;active=false;if(announce)await send({type:'leave'});if(backgroundPipeline){stopBackgroundPipeline(backgroundPipeline);backgroundPipeline=null;activeBackground='none'}if(customBackgroundUrl){URL.revokeObjectURL(customBackgroundUrl);customBackgroundUrl=null}media?.getTracks().forEach(t=>t.stop());media=null;[...peers.keys()].forEach(dropVideoStream);remoteStreams.clear();pendingIce.clear();players.delete(uid);renderPlayers();$('#nameInput').disabled=false;$('#joinBtn').innerHTML='ENTRAR NA MESA <span>→</span>';$('#videoGrid').innerHTML=videoPlaceholder();$('#rollStatus').textContent='VOCÊ SAIU DA SALA';}
function removePlayer(id){players.delete(id);dropVideoStream(id);renderPlayers();if(!$('#videoGrid').querySelector('.video-tile'))$('#videoGrid').innerHTML=videoPlaceholder()}
window.addEventListener('pagehide',()=>{if(active){const payload=JSON.stringify({room,event:{type:'leave',from:uid}});navigator.sendBeacon('/api/event',new Blob([payload],{type:'application/json'}))}});
function roomInviteUrl(){const invite=new URL(location.href);invite.searchParams.set('sala',room);return invite.href}function shareRoomLink(){const overlay=$('#inviteOverlay'),input=$('#inviteLinkInput');if(!overlay||!input){toast('Não foi possível abrir o convite. Atualize a página e tente novamente.');return}input.value=roomInviteUrl();overlay.hidden=false;requestAnimationFrame(()=>{input.focus();input.select()})}async function copyInviteLink(){const input=$('#inviteLinkInput'),status=$('#inviteCopyStatus');if(!input?.value)return;try{await navigator.clipboard.writeText(input.value);status.textContent='Link copiado. Envie-o aos jogadores.';toast('Link da sala copiado!')}catch{input.focus();input.select();let copied=false;try{copied=document.execCommand('copy')}catch{}status.textContent=copied?'Link copiado. Envie-o aos jogadores.':'Link selecionado. Use Copiar no menu do aparelho ou Ctrl+C.';if(copied)toast('Link da sala copiado!')}}function closeInvite(){const overlay=$('#inviteOverlay');if(overlay)overlay.hidden=true}$('#copyLink').addEventListener('click',shareRoomLink);$('#inviteBtn').addEventListener('click',shareRoomLink);$('#copyInviteBtn').addEventListener('click',copyInviteLink);$('#closeInviteBtn').addEventListener('click',closeInvite);$('#inviteOverlay').addEventListener('click',event=>{if(event.target.id==='inviteOverlay')closeInvite()});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeInvite()});
renderPlayers();poll();loadRoomBooks();

const inviteSocial=document.createElement('div');inviteSocial.className='invite-social';inviteSocial.innerHTML='<button type="button" data-social="whatsapp">WhatsApp</button><button type="button" data-social="facebook">Facebook</button><button type="button" data-social="native">Mais opções…</button>';document.querySelector('.invite-dialog').append(inviteSocial);inviteSocial.addEventListener('click',async event=>{const kind=event.target.dataset.social;if(!kind)return;const link=roomInviteUrl(),text='Entre na minha mesa AD&D: '+link;if(kind==='whatsapp')window.open('https://wa.me/?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');else if(kind==='facebook')window.open('https://www.facebook.com/sharer/sharer.php?u='+encodeURIComponent(link),'_blank','noopener,noreferrer');else if(navigator.share){try{await navigator.share({title:'Mesa Sombria',text:'Entre na minha mesa AD&D',url:link})}catch(error){if(error.name!=='AbortError')copyInviteLink()}}else copyInviteLink()});
